  "prompt": "Draft a short, warm referral-ask email for a happy Nivy client. Mention their unique link naturally, don't be salesy. Client: {{$json.name}}. Link: {{$json.referral_link}}. Return ONLY JSON with keys: subject, body."
}

={
  "jsonrpc": "2.0", "method": "call",
  "params": {
    "service": "object", "method": "execute_kw",
    "args": ["{{$env.ODOO_DB}}", {{$env.ODOO_UID}}, "{{$env.ODOO_API_KEY}}",
      "mail.channel", "message_post",
      [ [{{$env.ODOO_DISCUSS_CHANNEL_ID}}], {
        "body": {{JSON.stringify('REFERRAL PAYOUT DUE: referral code ' + $json.referral_code + ' converted (referred: ' + $json.referred_name + '). Amount NOT auto-calculated -- commission % is not yet defined in the KB. Process manually per your commission policy once set.')}}
      } ]
  }, "id": 1
}
